import{_ as t,o as a,c as i,aj as s}from"./framework.js";const k=JSON.parse('{"title":"k-data | K Data | Template Engine","description":"Declare data flow with HTML tags inside a template. This is the recommended approach and replaces deprecated k-query.","frontmatter":{"title":"k-data | K Data | Template Engine","description":"Declare data flow with HTML tags inside a template. This is the recommended approach and replaces deprecated k-query.","head":[["link",{"rel":"canonical","href":"https://docs.kooboo.com/templateEngine/k-data/index.html"}]]},"headers":[],"relativePath":"templateEngine/k-data/index.md","filePath":"en/templateEngine/k-data/index.md","lastUpdated":1786616667000}'),d={name:"templateEngine/k-data/index.md"};function o(n,e,l,r,c,h){return a(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="k-data" tabindex="-1">k-data <a class="header-anchor" href="#k-data" aria-label="Permalink to &quot;k-data&quot;">​</a></h1><blockquote><p>Declare data flow with HTML tags inside a template. This is the recommended approach and replaces deprecated <code>k-query</code>.</p></blockquote><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p><strong>k-data</strong> uses plain HTML tags such as <code>&lt;k-data&gt;</code>, <code>&lt;let&gt;</code>, and <code>&lt;query&gt;</code> to describe a full server-side data flow: read request values, query data, shape the result, and expose variables. Add the <code>export</code> attribute to the <code>&lt;query&gt;</code> or <code>&lt;let&gt;</code> that creates a value needed by the template.</p><p>Compared with the old single-attribute <strong><code>k-query</code></strong> syntax, k-data:</p><ul><li>has a fixed structure that is easier for AI generation and code review,</li><li>supports branches, exceptions, redirects, and field mapping,</li><li>and uses <strong>JSON5 conditions</strong> for <code>where</code> and <code>test</code> instead of SQL-like strings.</li></ul><div class="tip custom-block"><p class="custom-block-title">Division of responsibility with template bindings</p><table tabindex="0"><thead><tr><th>Layer</th><th>Syntax</th><th>Responsibility</th></tr></thead><tbody><tr><td>Inside <code>&lt;k-data&gt;</code></td><td><code>&lt;let&gt;</code>, <code>&lt;query&gt;</code>, <code>&lt;when&gt;</code> and friends</td><td>Prepare data</td></tr><tr><td>Template DOM</td><td><code>k-content</code>, <code>k-for</code>, <code>k-if</code>, <code>k-attribute</code></td><td>Render UI</td></tr></tbody></table><p>See <a href="./../binding/">Template Binding Syntax</a> for the rendering layer.</p></div><h2 id="minimal-runnable-example" tabindex="-1">Minimal Runnable Example <a class="header-anchor" href="#minimal-runnable-example" aria-label="Permalink to &quot;Minimal Runnable Example&quot;">​</a></h2><p>This example does one thing: query <code>article</code> content and display each title.</p><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">k-data</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &lt;</span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">query</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">        as</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;articles&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">        source</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;content&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">        resource</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;article&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">        action</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;list&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">        export</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &gt;&lt;/</span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">query</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">k-data</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">ul</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">li</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> k-for</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;article in articles&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">span</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> k-content</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;article.title&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">span</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">li</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">ul</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>This is the smallest complete data flow:</p><ol><li><code>&lt;query&gt;</code> fetches data and stores the result in <code>articles</code>.</li><li>The <code>export</code> attribute on <code>&lt;query&gt;</code> exposes <code>articles</code> to the template.</li><li><code>k-for</code> iterates over the result and <code>k-content</code> displays each title.</li></ol><div class="tip custom-block"><p class="custom-block-title">Before you run it</p><p>The site must have a Content Folder named <code>article</code> with a <code>title</code> field. Replace these names with the resource and field names used by your site.</p></div><h2 id="related-topics" tabindex="-1">Related Topics <a class="header-anchor" href="#related-topics" aria-label="Permalink to &quot;Related Topics&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Topic</th><th>Description</th><th>Documentation</th></tr></thead><tbody><tr><td>Fields and filters</td><td>Control query results with <code>select</code> and <code>where</code></td><td><a href="./query.html#content">Query Sources</a></td></tr><tr><td>Request input</td><td>Read values from URLs, cookies, headers, and other request sources</td><td><a href="./tags.html#let">Tag Syntax · let</a></td></tr><tr><td>Pagination and sorting</td><td>Use <code>paged</code>, <code>page-number</code>, and <code>order-desc</code></td><td><a href="./query.html#paged">Query Sources · paged</a></td></tr><tr><td>Mapping and formatting</td><td>Reshape fields and format display values</td><td><a href="./tags.html#map">Tag Syntax · map</a>, <a href="./functions.html">Built-in Functions</a></td></tr><tr><td>Conditions and errors</td><td>Branches, error handling, and redirects</td><td><a href="./condition.html">Condition Expressions</a>, <a href="./tags.html">Tag Syntax</a></td></tr></tbody></table><h2 id="authoring-conventions" tabindex="-1">Authoring Conventions <a class="header-anchor" href="#authoring-conventions" aria-label="Permalink to &quot;Authoring Conventions&quot;">​</a></h2><ol><li>Read external input with <code>source</code> plus <code>from</code>, such as <code>queryString</code> or <code>cookie</code>.</li><li>Use <code>source</code>, <code>resource</code>, and <code>action</code> for queries. Standardize pagination with <code>page-number</code> and <code>page-size</code>.</li><li>For <code>action=&quot;paged&quot;</code>, map the list with <code>from=&quot;result.list&quot;</code>.</li><li>In the template layer, use only variables exposed with the <code>export</code> attribute.</li><li><code>&lt;when&gt;</code>, <code>&lt;else-if&gt;</code>, and <code>&lt;else&gt;</code> belong only inside <code>&lt;k-data&gt;</code>. In the DOM layer, use <code>k-if</code>, <code>k-else-if</code>, and <code>k-else</code>.</li><li>The <code>{...}</code> syntax in <code>k-attribute</code> only interpolates variables. It does not perform calculations. Use <code>&lt;let use=&quot;add|subtract|...&quot;&gt;</code> first, then bind the result.</li><li><code>&lt;query&gt;</code> is not an HTML void element. Always include <code>&lt;/query&gt;</code>; do not write <code>&lt;query ... /&gt;</code>.</li></ol><h2 id="tag-summary" tabindex="-1">Tag Summary <a class="header-anchor" href="#tag-summary" aria-label="Permalink to &quot;Tag Summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tag</th><th>Responsibility</th></tr></thead><tbody><tr><td><code>k-data</code></td><td>Root container for the data flow</td></tr><tr><td><code>let</code></td><td>Variables, request input, or built-in function calls</td></tr><tr><td><code>query</code></td><td>Query content, commerce, database, and related sources</td></tr><tr><td><code>map</code></td><td>Map over an array or object</td></tr><tr><td><code>when</code> / <code>else-if</code> / <code>else</code></td><td>Conditional branches inside <code>k-data</code></td></tr><tr><td><code>try</code> / <code>catch</code></td><td>Exception handling</td></tr><tr><td><code>redirect</code></td><td>Server-side redirect</td></tr></tbody></table><p><code>export</code> is a boolean attribute on <code>&lt;query&gt;</code> and <code>&lt;let&gt;</code> that exposes their <code>as</code> variable to the template layer.</p><p>See <a href="./tags.html">Tag Syntax</a> for details.</p><h2 id="docs-in-this-section" tabindex="-1">Docs in This Section <a class="header-anchor" href="#docs-in-this-section" aria-label="Permalink to &quot;Docs in This Section&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Topic</th><th>Description</th></tr></thead><tbody><tr><td><a href="./tags.html">Tag Syntax</a></td><td><code>let</code>, <code>query</code>, <code>map</code>, branching, and exposing variables</td></tr><tr><td><a href="./query.html">Query Sources</a></td><td><code>content</code>, <code>commerce</code>, <code>sqlite</code>, <code>mysql</code>, <code>culture</code>, and more</td></tr><tr><td><a href="./functions.html">Built-in Functions</a></td><td><code>dateFormat</code>, <code>jwtDecode</code>, math, and text helpers</td></tr><tr><td><a href="./condition.html">Condition Expressions</a></td><td>JSON5 <code>where</code> and <code>test</code> syntax</td></tr></tbody></table><h2 id="relationship-to-kscript-apis" tabindex="-1">Relationship to KScript APIs <a class="header-anchor" href="#relationship-to-kscript-apis" aria-label="Permalink to &quot;Relationship to KScript APIs&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Scenario</th><th>Doc</th></tr></thead><tbody><tr><td>Declarative data fetching inside a template</td><td>This <code>k-data</code> section</td></tr><tr><td>CRUD or business logic in script code</td><td><a href="/kb-docs/api/content/">k.content</a>, <a href="/kb-docs/api/database/">k.DB</a>, <a href="/kb-docs/api/commerce/commerce.html">k.commerce</a> and related APIs</td></tr></tbody></table><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./../page/">Page</a> and <a href="./../view/">View</a></li><li><a href="./../binding/">Template Binding Syntax</a></li></ul>`,27)])])}const u=t(d,[["render",o]]);export{k as __pageData,u as default};
